INSERT OVERWRITE TABLE ${schema}.dwd_sr_data_warehouse_ni_all_cspu_link_hf
partition(grass_region = ${grass_region}, local_date, local_hour, regional_date,regional_hour)
select
     cspu_id
    ,model_id
    ,item_id
    ,shop_id
    ,biz_tag
    ,link_update_time as update_time

    ,date(date_timezone_convert(${regional_date},${regional_hour},'SG',${grass_region},"yyyy-MM-dd")) as local_date
    ,cast(date_timezone_convert(${regional_date},${regional_hour},'SG',${grass_region},"HH") as int) as local_hour
    ,cast(${regional_date} as date) as regional_date
    ,cast(${regional_hour} as int) as regional_hour
from paimon.rcmd_feature.ods_sr_data_warehouse_tc_cspu_model_link
where grass_region in (${grass_region}) and status=1
-- by 20260312：MPI不允许流控用的link的cspuid会被置null（手动删除也会是null，但是手动删除其余非modelid字段也是null）
and cspu_id is not null
-- by 20260312:该表只包含未退场的 新品特供的。newnew cspu更新了识别方式，包含退场为biz_tag=256，不包含退场为biz_tag=512
and (biz_tag & 512 > 0)
;
